<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {getQuestionnaire,submitQuestionnaire,getSavedProfile} from '@/api/questionnaire'
import {ApiError} from '@/api/client'
import {blankDraft,draftKey,receiptKey,id,initialAnswer,loadDraft,validateAnswer,type Draft,type Questionnaire,type Answer,type Receipt} from '@/questionnaire/model'
import {globalError} from '@/lib/errors'
import './questionnaire.css'

const config=ref<Questionnaire>(),draft=ref<Draft>(),receipt=ref<Receipt>(),profile=ref<unknown>(),loading=ref(true),submitting=ref(false),error=ref(''),notice=ref(''),errors=ref<string[]>([]),clearing=ref(false)
const current=computed(()=>config.value?.questions[draft.value?.currentIndex||0])
const answer=computed(()=>draft.value?.answers[current.value?.questionId||'']||{})
const module=computed(()=>config.value?.modules.find(m=>m.moduleId===current.value?.moduleId))
const completed=computed(()=>config.value?.questions.filter(q=>draft.value?.answers[q.questionId]&&validateAnswer(q,draft.value.answers[q.questionId]).length===0).length||0)
const issues=computed(()=>config.value?.questions.map((q,i)=>({q,i,errors:validateAnswer(q,draft.value?.answers[q.questionId])})).filter(x=>x.errors.length)||[])
function persist(){if(!config.value||!draft.value)return;draft.value.updatedAt=new Date().toISOString();try{localStorage.setItem(draftKey(config.value),JSON.stringify(draft.value))}catch{notice.value='此浏览器无法保存草稿，请保持页面打开直到提交完成。'}}
function go(index:number){if(!draft.value||!config.value)return;draft.value.currentIndex=index;draft.value.stage='question';errors.value=[];error.value='';if(!draft.value.answers[current.value!.questionId])draft.value.answers[current.value!.questionId]=initialAnswer(current.value!);persist();window.scrollTo(0,0)}
function mutate(fn:(a:Answer)=>void){if(!draft.value||!current.value||submitting.value)return;const a=draft.value.answers[current.value.questionId]||initialAnswer(current.value),previous=JSON.stringify({...a,skipped:Boolean(a.skipped)});a.skipped=false;fn(a);if(draft.value.attempted&&previous!==JSON.stringify(a)){draft.value.submissionId=id();draft.value.attempted=false;notice.value='已修改答卷，下一次将作为新提交处理。'}draft.value.answers[current.value.questionId]=a;errors.value=[];error.value='';persist()}
function select(option:string){mutate(a=>{if(current.value!.questionType.startsWith('SINGLE_'))a.selectedOptionIds=[option];else{const selected=a.selectedOptionIds||[];const exclusive=current.value!.selectionRules?.exclusiveOptionIds||[];if(selected.includes(option))a.selectedOptionIds=selected.filter(v=>v!==option);else if(exclusive.includes(option))a.selectedOptionIds=[option];else a.selectedOptionIds=[...selected.filter(v=>!exclusive.includes(v)),option]}})}
function field(key:string,value:string,kind:'fields'|'customTexts'|'anchors'='fields'){mutate(a=>{(a[kind]??={})[key]=value})}
function sub(key:string,value:string){mutate(a=>{(a.subAnswers??={})[key]=[value]})}
function multi(key:string,value:string){mutate(a=>{const values=a.selections?.[key]||[];(a.selections??={})[key]=values.includes(value)?values.filter(v=>v!==value):[...values,value]})}
function next(){if(!config.value||!draft.value||!current.value)return;errors.value=validateAnswer(current.value,answer.value);if(errors.value.length)return;if(draft.value.currentIndex===config.value.questions.length-1){draft.value.stage='review';persist();window.scrollTo(0,0)}else go(draft.value.currentIndex+1)}
function skip(){if(!current.value?.allowSkip)return;mutate(a=>{Object.keys(a).forEach(k=>delete a[k as keyof Answer]);a.skipped=true});next()}
function clear(){if(!config.value)return;notice.value='';try{localStorage.removeItem(draftKey(config.value));if(receipt.value)localStorage.removeItem(receiptKey(config.value))}catch{notice.value='浏览器未能清除旧草稿，请保持页面打开。'}draft.value=blankDraft(config.value);receipt.value=undefined;profile.value=undefined;clearing.value=false;errors.value=[];error.value='';globalError.value=''}
async function submit(){if(!draft.value||!config.value||submitting.value)return;if(issues.value.length){go(issues.value[0]!.i);errors.value=validateAnswer(current.value!,answer.value);return}submitting.value=true;error.value='';draft.value.attempted=true;persist();const submissionId=draft.value.submissionId
  try{const result=await submitQuestionnaire({submissionId,questionnaireId:config.value.questionnaireId,questionnaireVersion:config.value.version,answers:JSON.parse(JSON.stringify(draft.value.answers))});if(result.submissionId!==submissionId||result.processingStatus!=='COMPLETED'||!result.profileId)throw Error('服务器尚未确认保存，请保留草稿后重试。');receipt.value=result;notice.value='';globalError.value='';try{localStorage.setItem(receiptKey(config.value),JSON.stringify(result))}catch{notice.value='答卷已保存，请保留画像编号；此浏览器无法保存回执。'}try{localStorage.removeItem(draftKey(config.value))}catch{notice.value='已保存到服务器，但浏览器未能清除草稿。'}window.scrollTo(0,0)}
  catch(e){globalError.value='';error.value=e instanceof ApiError?e.response.message:e instanceof Error?e.message:'提交失败，草稿已保留。请重试。';if(e instanceof ApiError)errors.value=e.response.errors.map(item=>item.path+'：'+item.message)}finally{submitting.value=false}}
async function loadProfile(){if(receipt.value)try{profile.value=await getSavedProfile(receipt.value.profileId)}catch(e){error.value=e instanceof Error?e.message:'读取失败'}}
async function load(){loading.value=true;error.value='';try{config.value=await getQuestionnaire();try{const previous=loadDraft(config.value,localStorage);draft.value=previous||blankDraft(config.value);if(previous&&Object.keys(previous.answers).length)notice.value='已恢复此浏览器中的未提交草稿。';if(!previous){const stored=localStorage.getItem(receiptKey(config.value));if(stored){const value=JSON.parse(stored) as Receipt;if(value.processingStatus==='COMPLETED'&&typeof value.profileId==='string'&&value.questionnaireVersion===config.value.version)receipt.value=value}}}catch{draft.value=blankDraft(config.value);notice.value='旧草稿无法恢复，可以重新填写；旧数据将在你开始填写后替换。'}}catch(e){globalError.value='';error.value=e instanceof Error?e.message:'问卷加载失败'}finally{loading.value=false}}
onMounted(load)
</script>

<template>
  <div class="paid-questionnaire"><div class="paid-app">
    <header class="paid-masthead"><RouterLink to="/" class="paid-brand"><img src="/paid-mark.svg" width="30" height="30" alt="">AI 心动人格定制</RouterLink><span>深度偏好问卷</span></header>
    <p v-if="notice" class="paid-notice" role="status">{{notice}}</p>
    <div v-if="error" class="paid-error" role="alert">{{error}}<button v-if="!config" @click="load">重新加载</button></div>
    <p v-if="loading" class="paid-loading">正在准备你的问卷…</p>
    <template v-else-if="config&&draft">
      <section v-if="receipt" class="paid-card paid-success"><img src="/paid-mark.svg" width="82" height="82" alt=""><p class="paid-eyebrow">答卷已保存</p><h1>TA 的轮廓，<br>又清晰了一点。</h1><p>已整理你的偏好和对应依据。接下来还需要与你确认细节，这份档案还不是最终人格设定。</p><dl><dt>画像编号</dt><dd data-testid="profile-id">{{receipt.profileId}}</dd><dt>当前版本</dt><dd>{{receipt.profileVersion}}</dd><dt>处理状态</dt><dd>{{receipt.processingStatus==='COMPLETED'?'处理完成':'处理中'}} · {{receipt.readyForCompilation?'可进入后续编译':'待确认与澄清'}}</dd><dt>待处理事项</dt><dd>{{receipt.clarificationCount}} 项</dd></dl><button class="paid-primary" @click="loadProfile">查看已保存的偏好档案</button><details v-if="profile" class="paid-json"><summary>展开档案内容</summary><pre>{{JSON.stringify(profile,null,2)}}</pre></details><button class="paid-text" @click="clear">另填一份新答卷</button></section>
      <section v-else-if="draft.stage==='intro'" class="paid-intro"><p class="paid-eyebrow">26 个偏好设定 · 7 个模块</p><h1>让心动的原型，<br>多一点属于你的细节。</h1><img class="paid-cover-mark" src="/paid-mark.svg" width="142" height="142" alt="心形对话框"><p>从性格底色，到怎样倾听、怎样相处，<br>一步一步，描绘你希望的 TA。</p><p class="paid-duration">约 {{config.estimatedMinutes}} 分钟 · 可以随时返回修改</p><button class="paid-primary" @click="go(draft.currentIndex)">{{Object.keys(draft.answers).length?'继续填写':'开始塑造 TA'}}<span aria-hidden="true">→</span></button><p class="paid-privacy">未提交的答卷只暂存在当前浏览器。<br>清除浏览器数据或更换设备，可能丢失草稿。</p><button v-if="Object.keys(draft.answers).length" class="paid-text" @click="clearing=true">清除本地草稿</button></section>
      <section v-else-if="draft.stage==='review'" class="paid-review"><p class="paid-eyebrow">最后再看一眼</p><h1>这些偏好，<br>都和你的想法一致吗？</h1><p class="paid-subtitle">提交前可以返回任意题目。点击提交后，服务器才会接收完整答卷。</p><ul><li v-for="(q,index) in config.questions" :key="q.questionId"><button :disabled="submitting" @click="go(index)"><span>{{String(index+1).padStart(2,'0')}} · {{q.title}}</span><small>{{validateAnswer(q,draft.answers[q.questionId]).length?'待补充':draft.answers[q.questionId]?.skipped||!draft.answers[q.questionId]?'已跳过':'已填写'}}</small></button></li></ul><ul v-if="errors.length" class="paid-field-errors" role="alert"><li v-for="message in errors" :key="message">{{message}}</li></ul><p v-if="issues.length" class="paid-error">还有 {{issues.length}} 道题需要检查。</p><button class="paid-primary" data-testid="submit" :disabled="submitting" @click="submit">{{submitting?'正在提交，请稍候…':error?'重试提交（草稿已保留）':'提交我的偏好答卷'}}</button><button class="paid-text" :disabled="submitting" @click="go(config.questions.length-1)">返回修改</button><p class="paid-privacy">提交后生成待确认画像，不会直接生成最终人格提示词。</p></section>
      <section v-else-if="current" :key="current.questionId" class="paid-step"><div class="paid-progress-meta"><button class="paid-back" aria-label="上一题" @click="draft.currentIndex?go(draft.currentIndex-1):(draft.stage='intro',persist())">‹</button><div><strong>{{String(draft.currentIndex+1).padStart(2,'0')}}<small> / {{config.totalQuestions}}</small></strong><p>{{module?.title}}</p></div><button class="paid-text" @click="clearing=true">清除草稿</button></div><div class="paid-progress" role="progressbar" :aria-valuenow="completed" :aria-valuemax="config.totalQuestions" aria-valuemin="0" aria-label="整体答题进度"><span :style="{width:`${completed/config.totalQuestions*100}%`}"></span></div><p class="paid-module">{{module?.description}}<br>本模块 {{(module?.questionIds.indexOf(current.questionId)||0)+1}} / {{module?.questionIds.length}} 题 · 已填写 {{completed}} / {{config.totalQuestions}}</p>
        <article class="paid-card"><p class="paid-eyebrow">第 {{draft.currentIndex+1}} 题 · {{current.required?'必答':'可跳过'}}</p><h1>{{current.title}}</h1>
          <fieldset :disabled="submitting">
            <div v-if="current.options" class="paid-options"><p v-if="current.maxSelections" class="paid-help">请选择 {{current.minSelections}}–{{current.maxSelections}} 项</p><button v-for="(option,index) in current.options" :key="option.id" class="paid-option" :class="{selected:answer.selectedOptionIds?.includes(option.id)}" :data-option="option.id" :aria-pressed="!!answer.selectedOptionIds?.includes(option.id)" @click="select(option.id)"><span class="paid-letter">{{String.fromCharCode(65+index)}}</span><span>{{option.text||option.label}}</span></button></div>
            <div v-else-if="current.fields" class="paid-fields"><label v-for="f in current.fields" :key="f.fieldId" class="paid-field"><span>{{f.label}}</span><template v-if="f.type?.startsWith('MULTI_')"><div class="paid-chips"><button v-for="o in f.options" :key="o.id" type="button" :aria-pressed="!!answer.selections?.[f.fieldId]?.includes(o.id)" :class="{selected:answer.selections?.[f.fieldId]?.includes(o.id)}" @click.prevent="multi(f.fieldId,o.id)">{{o.label||o.text}}</button></div><input :aria-label="f.label+' 自定义'" placeholder="也可以补充一个自己的描述" maxlength="400" :value="answer.customTexts?.[f.fieldId]||''" @input="field(f.fieldId,($event.target as HTMLInputElement).value,'customTexts')"></template><template v-else-if="f.options"><select :aria-label="f.label" :value="answer.fields?.[f.fieldId]||''" @change="field(f.fieldId,($event.target as HTMLSelectElement).value)"><option value="" disabled>请选择</option><option v-for="o in f.options" :key="o.id" :value="o.id">{{o.label||o.text||o.id}}</option></select><input v-if="answer.fields?.[f.fieldId]==='ARC_CUSTOM'" aria-label="自定义关系设定" placeholder="写下你希望的关系设定" maxlength="400" :value="answer.customTexts?.[f.fieldId]||''" @input="field(f.fieldId,($event.target as HTMLInputElement).value,'customTexts')"></template><input v-else :aria-label="f.label" :placeholder="f.placeholder" :maxlength="f.maxLength" :value="answer.fields?.[f.fieldId]||''" @input="field(f.fieldId,($event.target as HTMLInputElement).value)"></label></div>
            <div v-else-if="current.subQuestions" class="paid-subquestions"><section v-for="s in current.subQuestions" :key="s.subId"><h2>{{s.prompt}}</h2><button v-for="o in s.options" :key="o.id" class="paid-option" :class="{selected:answer.subAnswers?.[s.subId]?.includes(o.id)}" :aria-pressed="!!answer.subAnswers?.[s.subId]?.includes(o.id)" @click="sub(s.subId,o.id)">{{o.text||o.label}}</button></section></div>
            <div v-else-if="current.slots" class="paid-fields"><label v-for="slot in current.slots" :key="slot.slotId" class="paid-field"><span>{{slot.label}}</span><textarea rows="3" maxlength="2000" :aria-label="slot.label" :placeholder="slot.placeholder" :value="answer.anchors?.[slot.slotId]||''" @input="field(slot.slotId,($event.target as HTMLTextAreaElement).value,'anchors')"></textarea></label></div>
            <div v-else class="paid-fields"><textarea rows="6" :maxlength="current.maxTextLength" :aria-label="current.title" :placeholder="current.placeholder||'写下你的想法…'" :value="answer.text||''" @input="mutate(a=>a.text=($event.target as HTMLTextAreaElement).value)"></textarea><p class="paid-help">原文会随答卷保留，后续可能还需要与你确认含义。</p></div>
          </fieldset><ul v-if="errors.length" class="paid-field-errors" role="alert"><li v-for="e in errors" :key="e">{{e}}</li></ul><div class="paid-actions"><button class="paid-primary" @click="next">{{draft.currentIndex===config.questions.length-1?'检查整份答卷':'下一题'}}<span aria-hidden="true">→</span></button><button v-if="current.allowSkip" class="paid-text" @click="skip">暂时跳过这题</button></div>
        </article><p class="paid-privacy">每次修改都会暂存在当前浏览器，最终提交前不会逐题发送到服务器。</p>
      </section>
      <div v-if="clearing" class="paid-dialog-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="clear-title" class="paid-card"><h2 id="clear-title">清除本地草稿？</h2><p>未提交的内容将被清除，已保存到服务器的历史画像不受影响。</p><button class="paid-primary" @click="clear">确认清除</button><button class="paid-text" @click="clearing=false">保留草稿</button></section></div>
    </template>
    <footer class="paid-footer">偏好需求采集 · 不代表经过科学验证的心理测量</footer>
  </div></div>
</template>
